import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第三十五章 丢失十四头牛的忧愁","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/35第三十五章 丢失十四头牛的忧愁.md","filePath":"meditation/巴利文大藏经/35第三十五章 丢失十四头牛的忧愁.md"}'),_={name:"meditation/巴利文大藏经/35第三十五章 丢失十四头牛的忧愁.md"};function r(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第三十五章-丢失十四头牛的忧愁" tabindex="-1">第三十五章 丢失十四头牛的忧愁 <a class="header-anchor" href="#第三十五章-丢失十四头牛的忧愁" aria-label="Permalink to &quot;第三十五章 丢失十四头牛的忧愁&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部7相应10经/许多女儿经(婆罗门相应/有偈篇/祇夜)</p><p>有个时候，佛陀住在骄萨罗国的某个密林中。那个时候，有个婆罗门丢失了十四头牛，他到处寻找这些自己丢失的牛，不知不觉的来到佛陀的住所，他看见佛陀正在密林中静坐。就对静坐中的佛陀说到：“我的十四头牛在六天前丢失了，我心急如焚、愁眉苦脸。然而在这里打坐的出家人，他没有十四头牛，他却是安宁快乐的。</p><p>这个打坐的出家人，他没有种菜，当别人菜地里的蔬菜全部枯死，没有收成的时候，他不会痛苦不堪。别人的菜地遇上灾年欠收，或者没有收成，别人心如刀绞、忧心忡忡。他不会心急如麻、叫苦连天，他还是能保持安宁与快乐。</p><p>这个打坐的出家人，他没有谷仓，当别人谷仓里的粮食全部都被老鼠偷吃完了，他也不会痛苦不堪。别人的谷仓里的粮食被老鼠全部都偷吃光了，别人由此暴跳如雷、火冒三丈。他不会勃然大怒、苦不堪言。他还是能保持安宁与快乐。</p><p>这个打坐的出家人，他没有盖的被子和毯子，当到七月的时候，那些跳蚤和虱子钻进别人的被子和毯子啃咬别人身体的时候，他不会痛苦不堪。别人的床上、被子、毯子里全部都是跳蚤和虱子，别人被跳蚤虱子侵扰啃咬的夜不能眠、叫苦连天。这个出家人不会寝不安席、痛苦不堪。他还是能保持安宁与快乐。</p><p>这个打坐的出家人，没有个儿子，也没有妻子女儿在他的身边陪伴，当别人的儿子、妻子女儿遇见灾祸，患上重病，或者死去，或者女儿的丈夫死去变成寡妇，别人呼天唤地、痛心切骨。他不会呼天号地、心如刀锉。他还是能保持安宁与快乐。</p><p>这个打坐的出家人，没有黄脸婆、糟糠之妻在他的身边陪伴，当别人晚上睡觉打呼噜的时候，被黄脸婆、糟糠之妻踢醒昏昏沉沉、闷闷不乐的时候。他不会夜不安眠、郁郁寡欢。他还是能保持安宁与快乐。</p><p>这个打坐的出家人，没有讨要钱财的债主。当别人的债主早上站在别人的大门外，堵截大叫：「还钱，还钱」，让别人寝食不安、焦眉愁眼的时候，他不会焦思苦虑、忧心如焚。他还是能保持安宁与快乐。</p><p>这时，婆罗门说偈言：</p><p>「到此沙门处，十四头之牛，</p><p>至今寻六日，不见其踪影。</p><p>然而此沙门，是为最安乐。</p><p>撒菜种于田，收获之最恶，</p><p>非一茎二茎。然而此沙门，</p><p>是为最安乐。谷仓尽而空，</p><p>鼠盛于其中，暴怒如烈火。</p><p>然而此沙门，是为最安乐。</p><p>敷席尽七月，床卧满蚤虱。</p><p>然而此沙门，是为最安乐。</p><p>一儿及二儿，亦有女七人，</p><p>非如成寡妇。然而此沙门，</p><p>是为最安乐。蹴褐色黑白，</p><p>斑点妇眠足。然而此沙门，</p><p>是为最安乐。债主朝来等，</p><p>立门以苛责。然而此沙门。</p><p>是为最安乐。」</p><p>佛陀说：“婆罗门，如来没有十四头牛，就不会丢失这些牛。当别人的十四头牛全部生病，或者全部丢失的时候，如来不会心急如焚、愁眉苦脸。别人到处寻找已经丢失六天的十四头牛，心如刀绞、忧心忡忡的时候，如来不会心急如麻、叫苦连天。如来能够保持内心的清净和安宁，既不会产生痛苦，也不会产生快乐，不会被这些事情束缚捆绑，不会被这些事情侵扰和困惑，就如同没有发生这些事情一样，内心不会生起喜怒哀乐等等一切的念想。</p><p>如来没有菜地，不种菜，当别人菜地里的蔬菜全部枯死，没有收成的时候，如来不会痛苦不堪。别人的菜地遇上灾年欠收，或者没有收成，别人心如刀绞、忧心忡忡。如来不会心急如麻、叫苦连天。如来能够保持内心的清净和安宁，既不会产生痛苦，也不会产生快乐，不会被这些事情束缚捆绑，不会被这些事情侵扰和困惑，就如同没有发生这些事情一样，内心不会生起喜怒哀乐等等一切的念想。</p><p>如来没有谷仓，当别人谷仓里的粮食全部都被老鼠偷吃完了，如来不会痛苦不堪。别人的谷仓里的粮食被老鼠全部都偷吃光了，别人由此暴跳如雷、火冒三丈。如来不会勃然大怒、苦不堪言。如来能够保持内心的清净和安宁，既不会产生痛苦，也不会产生快乐，不会被这些事情束缚捆绑，不会被这些事情侵扰和困惑，就如同没有发生这些事情一样，内心不会生起喜怒哀乐等等一切的念想。</p><p>如来没有盖的被子和毯子，当到七月的时候，那些跳蚤和虱子钻进别人的被子和毯子啃咬别人身体的时候，如来不会痛苦不堪。别人的床上、被子、毯子里全部都是跳蚤和虱子，别人被跳蚤虱子侵扰啃咬的夜不能眠、叫苦连天。如来不会寝不安席、痛苦不堪。如来能够保持内心的清净和安宁，既不会产生痛苦，也不会产生快乐，不会被这些事情束缚捆绑，不会被这些事情侵扰和困惑，就如同没有发生这些事情一样，内心不会生起喜怒哀乐等等一切的念想。</p><p>如来没有妻子、儿子、女儿在身边陪伴，当别人的妻子、儿子、女儿发生灾祸，患上重病，或者死去，或者女儿的丈夫死去变成寡妇，别人呼天唤地、痛心切骨。如来不会呼天号地、心如刀锉。如来能够保持内心的清净和安宁，既不会产生痛苦，也不会产生快乐，不会被这些事情束缚捆绑，不会被这些事情侵扰和困惑，就如同没有发生这些事情一样，内心不会生起喜怒哀乐等等一切的念想。</p><p>如来没有黄脸婆、糟糠之妻在身边陪伴，当别人晚上睡觉打呼噜的时候，被黄脸婆、糟糠之妻踢醒昏昏沉沉、闷闷不乐的时候。如来不会夜不安眠、郁郁寡欢。如来能够保持内心的清净和安宁，既不会产生痛苦，也不会产生快乐，不会被这些事情束缚捆绑，不会被这些事情侵扰和困惑，就如同没有发生这些事情一样，内心不会生起喜怒哀乐等等一切的念想。</p><p>如来没有讨要钱财的债主。当别人的债主早上站在别人的大门外，堵截大叫：「还钱，还钱」，让别人寝食不安、焦眉愁眼的时候，如来不会焦思苦虑、忧心如焚。如来能够保持内心的清净和安宁，既不会产生痛苦，也不会产生快乐，不会被这些事情束缚捆绑，不会被这些事情侵扰和困惑，就如同没有发生这些事情一样，内心不会生起喜怒哀乐等等一切的念想。”</p><p>这时，佛陀说偈言：</p><p>「婆罗门忧苦，失牛十四头，</p><p>至今寻六日，不见其踪影。</p><p>然而婆罗门，如来无悲喜。</p><p>婆罗门忧苦，撒菜种于田。</p><p>收获之最恶，非一茎二茎。</p><p>然而婆罗门，如来无悲喜。</p><p>婆罗门忧苦，谷仓尽而空，</p><p>鼠盛于其中，暴怒如烈火。</p><p>然而婆罗门，如来无悲喜。</p><p>婆罗门忧苦，敷席尽七月，</p><p>床卧满蚤虱。然而婆罗门，</p><p>如来无悲喜。婆罗门忧苦。</p><p>有一儿二儿，亦有女七人，</p><p>非如成寡妇。然而婆罗门，</p><p>如来无悲喜。婆罗门忧苦，</p><p>无蹴褐黑白，斑点妇眠足。</p><p>然而婆罗门，如来无悲喜。</p><p>婆罗门忧苦，债主朝来等，</p><p>迫取于欠债，立门以苛责。</p><p>然而婆罗门，如来无悲喜。」</p><p>佛陀说法后，婆罗门对佛陀说：“大德，哎呀，您说的太好了，看来我认为的快乐也是烦恼和痛苦呀，我明白了，当这些让我快乐的事物衰败、损坏的时候，我就会产生痛苦。当我失去这些让我快乐的事物的时候，我就会产生痛苦。我之前拥有这些事物产生了多大的快乐，当这些事物衰败、损坏，我失去这些的事物的时候，我就会产生多大的痛苦。</p><p>大德，您说的法犹如将歪倒的东西扶正，将隐藏的东西显现出来。您说的法犹如告诉迷路的人正确的道路，犹如在黑夜中点亮灯烛，让在黑暗中行走的人能够看见周围的东西。您说的其他法也是这样的吧，请您让我皈依您，皈依您的正法，皈依您的僧团。我愿意受持您制定的戒律，我愿意按您的正法去修行，我愿意在您这里出家修行。”</p><p>佛陀接受了婆罗门的皈依。婆罗门受具足戒后，就独自隐居，不放逸身体行为，口说言语，内心生起的念想，不去做恶行，他断恶修善，按佛陀的正法精进的修行。这个婆罗门之所以出家修行，就是想要通过对身体行为，口说言语，内心生起念想的修行，来让自己内心清净安宁，由此开启智慧，最终证悟圆满解脱的果位。不久后这位婆罗门证悟得知：「自己从这一世开始就不会再投生转世了，自己的修行已经圆满。该做的事情已经做好了，自己不会再有生死轮回的煎熬和痛苦了，自己已经从生死轮回中永远的解脱出来。」</p><p>这位婆罗门证悟了阿罗汉的解脱果位，他成为佛陀众多阿罗汉弟子中的一位。</p>',60)]))}const f=t(_,[["render",r]]);export{m as __pageData,f as default};
